describe('Password Strength Indicator', () => {
  beforeEach(() => {
    cy.visit('/password-reset');
    cy.get('[data-testid="password-input"]').as('passwordInput');
    cy.get('[data-testid="strength-indicator"]').as('strengthIndicator');
  });

  it('should display password strength indicator when user enters a password', () => {
    cy.get('@passwordInput').type('weak');
    cy.get('@strengthIndicator').should('be.visible');
    cy.get('@strengthIndicator').should('contain', 'Weak');
    cy.get('@strengthIndicator').should('have.class', 'strength-weak');
  });

  it('should update strength indicator from weak to strong as password complexity increases', () => {
    cy.get('@passwordInput').type('Pass123');
    cy.get('@strengthIndicator').should('contain', 'Medium');
    cy.get('@strengthIndicator').should('have.class', 'strength-medium');

    cy.get('@passwordInput').clear().type('SecureP@ssw0rd!Complex');
    cy.get('@strengthIndicator').should('contain', 'Strong');
    cy.get('@strengthIndicator').should('have.class', 'strength-strong');
  });

  it('should hide strength indicator when password field is empty', () => {
    cy.get('@passwordInput').type('password123');
    cy.get('@strengthIndicator').should('be.visible');

    cy.get('@passwordInput').clear();
    cy.get('@strengthIndicator').should('not.be.visible');
  });

  it('should display very weak indicator for single character password', () => {
    cy.get('@passwordInput').type('a');
    cy.get('@strengthIndicator').should('be.visible');
    cy.get('@strengthIndicator').should('contain', 'Very Weak');
    cy.get('@strengthIndicator').should('have.class', 'strength-very-weak');
  });

  it('should maintain strength indicator visibility while user is typing', () => {
    cy.get('@passwordInput').type('P', { delay: 100 });
    cy.get('@strengthIndicator').should('be.visible');

    cy.get('@passwordInput').type('a', { delay: 100 });
    cy.get('@strengthIndicator').should('be.visible');

    cy.get('@passwordInput').type('ss', { delay: 100 });
    cy.get('@strengthIndicator').should('be.visible');

    cy.get('@passwordInput').type('w0rd!', { delay: 100 });
    cy.get('@strengthIndicator').should('be.visible');
    cy.get('@strengthIndicator').should('have.class', 'strength-strong');
  });

  it('should handle special characters in password strength calculation', () => {
    cy.get('@passwordInput').type('Pass@#$%');
    cy.get('@strengthIndicator').should('contain', 'Strong');
    cy.get('@strengthIndicator').should('have.class', 'strength-strong');
  });

  it('should display correct strength for password with numbers only', () => {
    cy.get('@passwordInput').type('12345678');
    cy.get('@strengthIndicator').should('be.visible');
    cy.get('@strengthIndicator').should('contain', 'Medium');
  });
});
